const fs = require('fs');
const path = require('path');
const need = require('../ar-need.json').map((x) => x.k);
for (const k of need) {
  if (!T[k]) throw new Error('missing ' + k);
}
if (Object.keys(T).length !== need.length) {
  const extra = Object.keys(T).filter((k) => !need.includes(k));
  throw new Error('extra keys: ' + extra.join(', '));
}
fs.writeFileSync(path.join(__dirname, 'need-ar-pack.json'), JSON.stringify(T, null, 2));
console.log('need-ar-pack', Object.keys(T).length);
